function validate([root, leaf]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'root must be a non-empty level-order array.';
  const values = root.filter(v => v !== null);
  if (values.length < 2 || values.length > 100) return 'The tree has 2 to 100 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Node values are integers between -10^9 and 10^9.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  // Replay the level-order layout to count each node's children.
  const children = new Map();
  const queue = [root[0]];
  let next = 1;
  for (let head = 0; head < queue.length && next < root.length; head++) {
    let count = 0;
    for (let side = 0; side < 2 && next < root.length; side++, next++) {
      if (root[next] !== null) { queue.push(root[next]); count++; }
    }
    children.set(queue[head], count);
  }
  if (next < root.length) return 'root has values after the last node.';
  if (!Number.isInteger(leaf) || !values.includes(leaf)) return 'leaf must be the value of a node in the tree.';
  if ((children.get(leaf) ?? 0) > 0) return 'leaf must be a node with no children.';
  return null;
}

