function adapt(input, solve, kit) {
  const [root, leaf] = input;
  class Node {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.parent = null; }
  }
  // Build the tree level by level, linking every child back to its parent.
  const nodes = [new Node(root[0])];
  let next = 1;
  for (let head = 0; head < nodes.length && next < root.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < root.length && root[next] !== null) {
        const child = new Node(root[next]);
        child.parent = nodes[head];
        nodes[head][side] = child;
        nodes.push(child);
      }
      next++;
    }
  }
  const result = solve(nodes[0], nodes.find(node => node.val === leaf));
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return [];
  if (result.parent !== null && result.parent !== undefined) return 'The new root must have parent null.';
  // Write the returned tree in level order, checking that every child points back to its parent.
  const values = [];
  const seen = new Set();
  const queue = [result];
  for (let k = 0; k < queue.length; k++) {
    const node = queue[k];
    if (node === null) { values.push(null); continue; }
    if (seen.has(node)) throw new Error('The returned structure is not a tree: a node is reached twice.');
    seen.add(node);
    values.push(node.val);
    for (const child of [node.left ?? null, node.right ?? null]) {
      if (child !== null && child.parent !== node) return `Node ${child.val} has a wrong parent link.`;
      queue.push(child);
    }
  }
  while (values.length && values[values.length - 1] === null) values.pop();
  return values;
}

