    }
    if (oldParent.left === node) {
      oldParent.left = null;
    } else {
      oldParent.right = null;
    }
    if (node.left !== null) {
      node.right = node.left;
    }
    node.left = reroot(oldParent, node);
    return node;
  }

  return reroot(leaf, null);
}

