  // List the path leaf -> root first, and each path node's off-path child, before changing anything.
  const path = [];
  for (let node = leaf; node !== null; node = node.parent) path.push(node);
  const last = path.length - 1;
  const offPath = path.map((node, i) => i === 0 ? null : node.left === path[i - 1] ? node.right : node.left);
  const rootLeftOnPath = root.left === path[last - 1];
  for (let i = 0; i <= last; i++) {
    const node = path[i];
    node.parent = i === 0 ? null : path[i - 1];
    if (i === last) {
      if (rootLeftOnPath) node.left = null; else node.right = null;
    } else {
      node.left = path[i + 1];
      node.right = offPath[i];
    }
  }
  return leaf;
}

